 async void RunSuburbChecks(){try{game.NoDiskSave=true;ClearEnemies();Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);SpawnObjects();DrawRescueDog(0);MigrationChecks.Assert(Enumerable.Range(0,8).All(i=>props.Any(p=>p.Id==$"suburb/{game.Save.Seed}/cache/{i}")),"Eight finite neighborhood caches spawned");MigrationChecks.Assert(props.Count(p=>p.Id.StartsWith($"suburb/{game.Save.Seed}/wreck/"))==8,"Eight salvagable driveway cars");MigrationChecks.Assert(props.Count(p=>p.Id.StartsWith($"suburb/{game.Save.Seed}/tree/"))>=8,"Harvestable yard trees streamed");MigrationChecks.Assert(Dog.RescueVersion==1&&!Dog.Rescued&&game.World.Tier(Dog.X,Dog.Z)==2&&Distance(DogPoint,player.Position)>500&&!DogPresent,"Dog waits at later woodland rescue");
 await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);
 for(int i=0;i<8;i++){var tr=SuburbHouseRoot(i);var start=tr.Transform*new Vector3(0,1.2f,13);var end=tr.Transform*new Vector3(0,1.2f,0);var q=PhysicsRayQueryParameters3D.Create(start,end);q.Exclude=new Godot.Collections.Array<Rid>{player.GetRid()};MigrationChecks.Assert(GetWorld3D().DirectSpaceState.IntersectRay(q).Count==0,"Home entrance remains physically open / "+i);tr.Free();}
 var p=SuburbHousePoint(0);MigrationChecks.Assert(!SuburbPaved(ExpeditionWorld.SpawnX-25,ExpeditionWorld.SpawnZ+10),"Common remains a buildable lawn");ShowSuburbGuide();MigrationChecks.Assert(menu.FindChildren("*","Button",true,false).OfType<Button>().Count(b=>b.Text.StartsWith("SHOW ON MAP"))==9,"Neighborhood guide pins every house and common");CloseMenu();
 Teleport(KennelX,KennelZ+3);SpawnDogRescue();DrawRescueDog(0);MigrationChecks.Assert(props.Any(p=>p.Id=="story/kennel")&&Enumerable.Range(0,3).All(i=>infected.Any(e=>e.Id==KennelGuardId(i))),"Kennel guards and cage present");int food=game.Life.Food;game.Life.Food=3;DogAction("rescue");MigrationChecks.Assert(!Dog.Rescued&&game.Life.Food==3,"Guarded dog cannot be claimed for food");foreach(var e in infected.Where(e=>e.Id.StartsWith("story/kennel/")).ToArray())KillEnemy(e);int rescueFood=game.Life.Food;DogAction("rescue");MigrationChecks.Assert(Dog.Rescued&&game.Life.Food==rescueFood-1&&!props.Any(p=>p.Id=="story/kennel"),"Clear guards, open kennel, recruit once / clear="+KennelClear+" near="+DogNear+" rescued="+Dog.Rescued+" food="+game.Life.Food+" notice="+game.Notice);DogAction("rescue");MigrationChecks.Assert(game.Life.Food==rescueFood-1,"Dog rescue does not duplicate cost");game.Life.Food=food;
 GD.Print("PASS / suburb: eight homes/caches, driveway salvage, harvestable landscaping, buildable common, location buttons, later T2 kennel, guard gate and one-time dog recruitment");SetProcess(false);SetPhysicsProcess(false);ClearEnemies();rescueDogActor?.Body.QueueFree();rescueDogActor=null;ClearChildren(worldRoot);ClearChildren(terrainRoot);ClearChildren(buildRoot);props.Clear();chunks.Clear();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);GetTree().Quit();}catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
 async void CaptureSuburb(){try{CloseMenu();game.World.Changes.Time=900;Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);SpawnObjects();ClearEnemies();paused=true;weaponRoot.Visible=false;hudRoot.Visible=false;camera.Fov=65;camera.GlobalPosition=Ground(ExpeditionWorld.SpawnX+2,ExpeditionWorld.SpawnZ+3)+Vector3.Up*2.2f;camera.LookAt(Ground(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ-62)+Vector3.Up*2);await ArtShot("suburb-01-briar-lane-street");camera.GlobalPosition=Ground(ExpeditionWorld.SpawnX+90,ExpeditionWorld.SpawnZ+48)+Vector3.Up*90;camera.LookAt(Ground(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ-65));await ArtShot("suburb-02-neighborhood-layout");GD.Print("PASS / suburb captures");GetTree().Quit();}catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
